  var peakOffset=MAX_OFFSET*0.5;  // 195
  var c = {_time:42, _velocity:0.1};
  c._time += c._velocity;  // 42.1

  // Old method
  var old_vals = [];
  for(var i=Math.min(5,POINTS);i>0;i--){
    var value=i*SPACING+(c._time%SPACING);
    var ax=Math.sin(value/POINTS_PER_LAP)*Math.PI;
    var ay=Math.cos(value/POINTS_PER_LAP)*Math.PI;
