  var timeMod=c._time%SPACING;
  var invLap=Math.PI/POINTS_PER_LAP;
  var invMax=1/MAX_OFFSET;
  var halfVal=0.5;
  var shearVal=0.2;
  for(var i=Math.min(5,POINTS);i>0;i--){
    var value=i*SPACING+timeMod;
    var angle=value*invLap;
    var ax=Math.sin(angle);
    var ay=Math.cos(angle);
    var x=ax*value;
    var y=ay*value*0.35;
    var o=1-(Math.min(value,PEAK)/PEAK);
    y-=o*o*peakOffset;
    y+=value*halfVal;
    y+=x*shearVal;
    var alpha=1-value*invMax;
    new_vals.push({x:x,y:y,o:o,alpha:alpha,ax:ax,ay:ay});
